from dataclasses import dataclass, field
from typing import Optional
from mashumaro import DataClassDictMixin, field_options
from mashumaro.config import BaseConfig
@dataclass
class C(DataClassDictMixin):
 x: int = field(metadata=field_options(alias='xx'))
class Conf(BaseConfig):
 serialize_by_alias=False
@dataclass
class P(DataClassDictMixin):
 c: C = field(metadata=field_options(flatten=True))
 class Config(Conf): pass
p=P(C(1)); print('unaliased:',p.to_dict())
try: print('roundtrip:',P.from_dict(p.to_dict()))
except Exception as e: print('roundtrip failed:',repr(e))
@dataclass
class O(DataClassDictMixin):
 c: Optional[C] = field(default=None,metadata=field_options(flatten=True,flatten_prefix=True))
print('optional:',O.from_dict({}), O(None).to_dict())
